-- Run inside a savepoint with producers.test.mjs's synthetic A/B fixture.
SELECT no_plan();
SELECT ok(NOT has_function_privilege('anon','public.listar_notificacoes_filtradas(text,uuid,text,integer,timestamptz,uuid)','EXECUTE'),'anon cannot list');
SELECT ok(NOT has_function_privilege('service_role','public.listar_notificacoes_filtradas(text,uuid,text,integer,timestamptz,uuid)','EXECUTE'),'UI never uses service role');
SELECT ok(NOT has_function_privilege('anon','public.obter_destino_notificacao(uuid,text,uuid)','EXECUTE'),'anon cannot open href');
SELECT ok(NOT has_function_privilege('authenticated','private.notificacao_destinatarios_entidade(text,uuid,text,boolean)','EXECUTE'),'recipient directory is private');
SELECT is((SELECT count(*) FROM private.notificacao_destinatarios_entidade('nota_fiscal','2a000000-0000-4000-8000-000000000001','gestor')),1::bigint,'only canonical gestor A');
SELECT is((SELECT count(*) FROM private.notificacao_destinatarios_entidade('nota_fiscal','2a000000-0000-4000-8000-000000000001','cedente')),1::bigint,'canonical cedente');
SELECT is((SELECT count(*) FROM private.notificacao_destinatarios_entidade('nota_fiscal','2a000000-0000-4000-8000-000000000001','sacado')),1::bigint,'exact CNPJ and fund Sacado');
SELECT is((SELECT count(*) FROM private.notificacao_destinatarios_entidade('nota_fiscal','2a000000-0000-4000-8000-000000000001','consultor')),2::bigint,'operator and reader current organizational access');
SELECT is((SELECT count(*) FROM public.notificar_entidade('nota_fiscal','2a000000-0000-4000-8000-000000000001','gestor','A1','QA','nf_aprovada','ui:a1')),1::bigint,'entity creates A1');
SELECT is((SELECT count(*) FROM public.notificar_entidade('nota_fiscal','2a000000-0000-4000-8000-000000000001','gestor','A1','QA','nf_aprovada','ui:a1')),0::bigint,'entity retry dedupes');
SELECT is((SELECT count(*) FROM public.notificar_entidade('entrega','2d000000-0000-4000-8000-000000000001','gestor','A2','QA','canhoto_enviado','ui:a2')),1::bigint,'logistics creates A2');
SELECT is((SELECT count(*) FROM public.notificar_entidade('cedente_fundo','24000000-0000-4000-8000-000000000002','gestor','B1','QA','operacao_aprovada','ui:b1')),2::bigint,'B includes both B memberships');
SELECT is((SELECT count(*) FROM public.notificacoes WHERE scope_type='FUNDO'),4::bigint,'rows include explicit scope');
SELECT ok((SELECT bool_and(href='/notificacoes/abrir/'||id||'?fundo='||fundo_id) FROM public.notificacoes),'all hrefs include fund');
SELECT set_config('request.jwt.claims','{"sub":"21000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000001')),2::bigint,'A list excludes B');
SELECT is((SELECT count(*) FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000002')),1::bigint,'B list excludes A');
SELECT is((SELECT nao_lidas FROM public.contar_notificacoes('FUNDO','22000000-0000-4000-8000-000000000001')),2::bigint,'A badge 2');
SELECT is((SELECT nao_lidas FROM public.contar_notificacoes('FUNDO','22000000-0000-4000-8000-000000000002')),1::bigint,'B badge 1');
SELECT is((SELECT count(*) FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000001','documentos')),1::bigint,'document category before pagination');
SELECT is((SELECT count(*) FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000001','logistica')),1::bigint,'logistics category');
SELECT is((SELECT count(*) FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000001','integracoes')),0::bigint,'empty integration category');
SELECT is((SELECT count(*) FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000001','alertas')),0::bigint,'empty alerts category');
SELECT is((SELECT count(*) FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000002','operacoes')),1::bigint,'operations category');
SELECT throws_ok($$SELECT * FROM public.listar_notificacoes_filtradas('FUNDO',NULL)$$,'42501',NULL,'null is not all funds');
SELECT throws_ok($$SELECT * FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000003')$$,'42501',NULL,'unauthorized C denied');
SELECT throws_ok($$SELECT * FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000001','invalid')$$,'22023',NULL,'unknown filter denied');
SELECT throws_ok($$SELECT * FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000001','todas',41)$$,'22023',NULL,'unbounded list denied');
SELECT is((SELECT count(*) FROM public.obter_destino_notificacao((SELECT id FROM public.notificacoes WHERE titulo='A1'),'FUNDO','22000000-0000-4000-8000-000000000001')),1::bigint,'authorized href resolves exact entity');
SELECT throws_ok($$SELECT * FROM public.obter_destino_notificacao((SELECT id FROM public.notificacoes WHERE titulo='A1'),'FUNDO','22000000-0000-4000-8000-000000000002')$$,'42501',NULL,'href A with authorized B context denied');
SELECT throws_ok($$SELECT * FROM public.obter_destino_notificacao((SELECT id FROM public.notificacoes WHERE titulo='A1'),'FUNDO','22000000-0000-4000-8000-000000000003')$$,'42501',NULL,'href unauthorized C denied');
SELECT throws_ok($$SELECT public.marcar_notificacoes_lidas('FUNDO','22000000-0000-4000-8000-000000000001',(SELECT id FROM public.notificacoes WHERE titulo='B1'))$$,'42501',NULL,'mark B id while A denied');
SELECT is(public.marcar_notificacoes_lidas('FUNDO','22000000-0000-4000-8000-000000000001'),2,'mark-all A');
SELECT is((SELECT nao_lidas FROM public.contar_notificacoes('FUNDO','22000000-0000-4000-8000-000000000001')),0::bigint,'A badge 0 after mark-all');
SELECT is((SELECT nao_lidas FROM public.contar_notificacoes('FUNDO','22000000-0000-4000-8000-000000000002')),1::bigint,'B unread remains unchanged');
SELECT is((SELECT count(*) FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000001','nao_lidas')),0::bigint,'unread filter after marking');
SELECT is((SELECT count(*) FROM public.listar_notificacoes_filtradas('FUNDO','22000000-0000-4000-8000-000000000001','lidas')),2::bigint,'read filter after marking');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"21000000-0000-4000-8000-000000000006","role":"authenticated","aal":"aal2"}',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT * FROM public.obter_destino_notificacao('2f000000-0000-4000-8000-000000000999','FUNDO','22000000-0000-4000-8000-000000000002')$$,'42501',NULL,'unknown notification denied');
SELECT is((SELECT count(*) FROM public.notificacoes WHERE titulo='A1'),0::bigint,'RLS hides A ID from B-only user');
RESET ROLE;
SELECT * FROM finish();
